# calculate current transform's chosen row/column line indices and divider on test and demo
from collections import Counter

def inspect(g):
 h,w=len(g),len(g[0]); fill=Counter(v for row in g for v in row).most_common(1)[0][0]
 def lp(axis):
  n=h if axis==0 else w; m=w if axis==0 else h; result=[]
  for i in range(n):
   vals=[g[i][j] if axis==0 else g[j][i] for j in range(m)]
   counts=Counter(v for v in vals if v!=fill)
   if counts and max(counts.values())/m>=.65: result.append(i)
  return result
 rows,cols=lp(0),lp(1)
 cnt=Counter()
 for r in rows: cnt.update(v for v in g[r] if v!=fill)
 for c in cols: cnt.update(g[r][c] for r in range(h) if g[r][c]!=fill)
 return fill,rows,cols,cnt
print(inspect(grid)); print(inspect(demo))

d3=[]
for r in range(22):
    if r in (8,20):
        row=[5]*30; row[3]=row[28]=0
    else:
        row=[4]*30; row[3]=row[28]=5
    d3.append(row)
print(v2.transform(d3))

def lattice(g):
 f=Counter(v for row in g for v in row).most_common(1)[0][0]
 h,w=len(g),len(g[0])
 def lpos(ax):
  n=h if ax==0 else w; m=w if ax==0 else h; out=[]
  for i in range(n):
   a=[g[i][j] if ax==0 else g[j][i] for j in range(m)]
   c=Counter(v for v in a if v!=f)
   if c and max(c.values())/m>=.65: out.append(i)
  return out
 rs,cs=lpos(0),lpos(1)
 return f,rs,cs,[[g[r][c] for c in cs] for r in rs]
for name,g in [('d1',demo),('d2',demo2),('d4',demo4),('d5',d5),('test',grid)]:
 f,rs,cs,M=lattice(g)
 print(name, f,rs,cs,M)

def debug(g):
 f,rs,cs,M=lattice(g)
 lc=Counter()
 for r in rs:lc.update(v for v in g[r] if v!=f)
 for c in cs:lc.update(g[r][c] for r in range(len(g)) if g[r][c]!=f)
 return f,rs,cs,lc,lc.most_common(1)[0][0]
for nm,gg in [('d1',demo),('d2',demo2),('d4',demo4),('d7',d7),('d8',d8),('test',grid)]:print(nm,debug(gg)[0],debug(gg)[-2:])

def diag_diff(g, expected, fill):
 f,rs,cs,M=lattice(g)
 # run all aligned full cell grid; account expected clipping via v2 output's crop coordinates as the intended array dimensions
 # list nontrivial diagonal-equal cells that are not four-equal
 out=[]
 for r in range(len(M)-1):
  for c in range(len(M[0])-1):
   a,b=M[r][c],M[r][c+1]; d,e=M[r+1][c],M[r+1][c+1]
   if a==e and a not in (fill,) and len({a,b,d,e})>1: out.append((r,c,a,b,d,e))
   if b==d and b not in (fill,) and len({a,b,d,e})>1: out.append((r,c,b,a,e,d))
 return out
for nm,gg,exp,fill in [('d1',demo,expected1,9),('d2',demo2,expected2,7),('d4',demo4,[[7,6,6],[6,6,8],[2,6,8]],6),('d7',d7,[[9,3,3,9,5],[3,9,9,9,9],[3,9,8,9,2]],9),('d8',d8,[[3,3,2,9],[3,2,2,2],[3,2,2,2],[3,2,5,2]],2)]: print(nm,diag_diff(gg,exp,fill))

